(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)');if(reduced.matches||!matchMedia('(pointer:fine)').matches)return;const intro=document.querySelector('.intro');if(intro){intro.addEventListener('pointermove',e=>{const r=intro.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;intro.style.transform=`perspective(1400px) rotateX(${-y*1.5}deg) rotateY(${x*1.5}deg)`});intro.addEventListener('pointerleave',()=>intro.style.transform='')};document.querySelectorAll('.grand-compass').forEach(compass=>{const stage=compass.closest('.compass-stage')||compass.parentElement;stage.addEventListener('pointermove',e=>{const r=stage.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;compass.style.setProperty('--tilt-x',`${6-y*10}deg`);compass.style.setProperty('--tilt-y',`${x*12}deg`)});stage.addEventListener('pointerleave',()=>{compass.style.setProperty('--tilt-x','7deg');compass.style.setProperty('--tilt-y','-4deg')})})})();
